25	namespace Catlass::Gemm::Block {
26	
27	template <
28	    class ArchTag_, bool ENABLE_UNIT_FLAG_, bool USE_HF32_MODE_, uint32_t L0C_STAGES_, bool ENABLE_L1_RESIDENT_,
29	    uint32_t L1A_STAGES_, uint32_t L1B_STAGES_, uint32_t L0A_STAGES_, uint32_t L0B_STAGES_, class L1TileShape_,
30	    class L0TileShape_, class ElementA_, class ElementB_, class ElementC_, class ElementBias_, class TileCopy_,
31	    class TileMmad_>
32	struct BlockMmadTla<
33	    MmadPingpongMutex<
34	        ArchTag_, ENABLE_UNIT_FLAG_, USE_HF32_MODE_, L0C_STAGES_, ENABLE_L1_RESIDENT_, L1A_STAGES_, L1B_STAGES_,
35	        L0A_STAGES_, L0B_STAGES_>,
36	    L1TileShape_, L0TileShape_, ElementA_, ElementB_, ElementC_, ElementBias_, TileCopy_, TileMmad_> {
37	public:
38	    // Type Aliases
39	    using DispatchPolicy = MmadPingpongMutex<
40	        ArchTag_, ENABLE_UNIT_FLAG_, USE_HF32_MODE_, L0C_STAGES_, ENABLE_L1_RESIDENT_, L1A_STAGES_, L1B_STAGES_,
41	        L0A_STAGES_, L0B_STAGES_>;
42	    using ArchTag = typename DispatchPolicy::ArchTag;
43	    using TileCopy = TileCopy_;
44	    using L1TileShape = L1TileShape_;
45	    using L0TileShape = L0TileShape_;
46	    using ElementA = ElementA_;
47	    using LayoutA = typename TileCopy::LayoutA;
48	    using ElementB = ElementB_;
49	    using LayoutB = typename TileCopy::LayoutB;
50	    using ElementC = ElementC_;
51	    using LayoutC = typename TileCopy::LayoutC;
52	    using ElementBias = ElementBias_;
53	
54	    using TileMmad = TileMmad_;
55	
56	    using CopyL1ToL0A = typename TileCopy::CopyL1ToL0A;
57	    using CopyL1ToL0B = typename TileCopy::CopyL1ToL0B;
58	    using CopyL1ToBT = typename TileCopy::CopyL1ToBT;
59	
60	    using ElementAccumulator = typename TileCopy::ElementAccumulator;
61	
62	    static constexpr bool HAS_BIAS = TileCopy::HAS_BIAS;
63	
64	    using LayoutTagL1A = typename TileCopy::LayoutTagL1A;
65	    using LayoutTagL1B = typename TileCopy::LayoutTagL1B;
66	    using LayoutTagL0A = typename TileCopy::LayoutTagL0A;
67	    using LayoutTagL0B = typename TileCopy::LayoutTagL0B;
68	
69	    using L1AAlignHelper = typename TileCopy_::L1AAlignHelper;
70	    using L1BAlignHelper = typename TileCopy_::L1BAlignHelper;
71	
72	    static_assert(
73	        tla::is_tuple<L1TileShape>::value && tla::is_static<L1TileShape>::value,
74	        "L1TileShape must be tla::tuple and static!");
75	    static_assert(
76	        tla::is_tuple<L0TileShape>::value && tla::is_static<L0TileShape>::value,
77	        "L0TileShape must be tla::tuple and static!");
78	
79	    static constexpr bool ENABLE_UNIT_FLAG = DispatchPolicy::ENABLE_UNIT_FLAG;
80	    static constexpr bool USE_HF32_MODE = DispatchPolicy::USE_HF32_MODE;
81	    static constexpr bool ENABLE_L1_RESIDENT = DispatchPolicy::ENABLE_L1_RESIDENT;
82	    static constexpr uint32_t L1A_STAGES = DispatchPolicy::L1A_STAGES;
83	    static constexpr uint32_t L1B_STAGES = DispatchPolicy::L1B_STAGES;
84	    static constexpr uint32_t L0A_STAGES = DispatchPolicy::L0A_STAGES;
85	    static constexpr uint32_t L0B_STAGES = DispatchPolicy::L0B_STAGES;
86	    static constexpr uint32_t L0C_STAGES = DispatchPolicy::L0C_STAGES;
87	    static constexpr uint32_t L1_TILE_M = tla::get<0>(L1TileShape{});
88	    static constexpr uint32_t L1_TILE_N = tla::get<1>(L1TileShape{});
89	    static constexpr uint32_t L1_TILE_K = tla::get<2>(L1TileShape{});
90	    static constexpr uint32_t L0_TILE_M = tla::get<0>(L0TileShape{});
91	    static constexpr uint32_t L0_TILE_N = tla::get<1>(L0TileShape{});
92	    static constexpr uint32_t L0_TILE_K = tla::get<2>(L0TileShape{});
93	
94	    // L1 tile size
95	    static constexpr uint32_t L1A_TILE_SIZE = L1_TILE_M * L1_TILE_K * sizeof(ElementA);
96	    static constexpr uint32_t L1B_TILE_SIZE = L1_TILE_N * L1_TILE_K * sizeof(ElementB);
97	    // L0 tile size
98	    static constexpr uint32_t L0A_TILE_SIZE = L0_TILE_M * L0_TILE_K * sizeof(ElementA);
99	    static constexpr uint32_t L0B_TILE_SIZE = L0_TILE_K * L0_TILE_N * sizeof(ElementB);
100	    static constexpr uint32_t L0C_TILE_SIZE = L1_TILE_M * L1_TILE_N * sizeof(ElementAccumulator);
101	
102	    // Check HF32_MODE
103	    static_assert(
104	        !USE_HF32_MODE || (USE_HF32_MODE && std::is_same_v<ElementA, float> && std::is_same_v<ElementB, float>),
105	        "HF32 MODE only supports in float!");
106	
107	    // Check L0C_STAGES
108	    static_assert(!(ENABLE_UNIT_FLAG && L0C_STAGES != 1), "L0C_STAGES must be 1 when UnitFlag is true!");
109	
110	    // Check LayoutC
111	    static_assert(
112	        tla::detail::isRowMajor<LayoutC>::value ||
113	            ((std::is_same_v<ElementC, half> || std::is_same_v<ElementC, bfloat16_t> ||
114	              std::is_same_v<ElementC, float>) &&
115	             tla::detail::iszN<ElementC, LayoutC>::value),
116	        "LayoutC only supports zN in half or bfloat16 or float, RowMajor in all dtype yet!");
117	
118	    // Check L1TileShape
119	    static_assert(
120	        L1A_TILE_SIZE * L1A_STAGES + L1B_TILE_SIZE * L1B_STAGES <= ArchTag::L1_SIZE,
121	        "L1TileShape exceeding the L1 space!");
122	
123	    // Check L0TileShape
124	    static_assert(L0A_TILE_SIZE * L0A_STAGES <= ArchTag::L0A_SIZE, "L0TileShape exceeding the L0A space!");
125	    static_assert(L0B_TILE_SIZE * L0B_STAGES <= ArchTag::L0B_SIZE, "L0TileShape exceeding the L0B space!");
126	    static_assert(L0C_TILE_SIZE * L0C_STAGES <= ArchTag::L0C_SIZE, "L0TileShape exceeding the L0C space!");
127	
128	    static_assert(
129	        L1_TILE_M == L0_TILE_M && L1_TILE_N == L0_TILE_N,
130	        "The situation where the basic blocks of L1 and L0 differ on the m and n axes is not supported yet");
131	    static_assert(L0_TILE_K <= L1_TILE_K, "L0TileShape::K cannot exceed L1TileShape::K");
132	
133	    static constexpr uint32_t L1A_MUTEX_OFFSET = 0;
134	    static constexpr uint32_t L1B_MUTEX_OFFSET = L1A_MUTEX_OFFSET + L1A_STAGES;
135	    static constexpr uint32_t L0A_MUTEX_OFFSET = L1B_MUTEX_OFFSET + L1B_STAGES;
136	    static constexpr uint32_t L0B_MUTEX_OFFSET = L0A_MUTEX_OFFSET + L0A_STAGES;
137	    static constexpr uint32_t L0C_MUTEX_OFFSET = L0B_MUTEX_OFFSET + L0B_STAGES;
138	    static constexpr uint32_t L1_BIAS_MUTEX_ID = L0C_MUTEX_OFFSET + L0C_STAGES;
139	    static constexpr uint32_t L0_BIAS_MUTEX_ID = L1_BIAS_MUTEX_ID + (HAS_BIAS ? 1 : 0);
140	    static constexpr uint32_t TOTAL_MUTEX_IDS = L0_BIAS_MUTEX_ID + (HAS_BIAS ? 1 : 0);
141	    static_assert(TOTAL_MUTEX_IDS <= 28, "MutexID overflow: Exceeds the supported range of MutexID(0~27)");
142	
143	    static constexpr auto L1A_LAYOUT =
144	        tla::MakeLayout<ElementA, LayoutTagL1A>(tla::Int<L1_TILE_M>{}, tla::Int<L1_TILE_K>{});
145	    static constexpr auto L1B_LAYOUT =
146	        tla::MakeLayout<ElementB, LayoutTagL1B>(tla::Int<L1_TILE_K>{}, tla::Int<L1_TILE_N>{});
147	    static constexpr auto L1BIAS_LAYOUT = tla::MakeLayout(tla::Int<L1_TILE_N>{});
148	    static constexpr auto L0BIAS_LAYOUT = tla::MakeLayout(tla::Int<L0_TILE_N>{});
149	
150	    // When enabling L1 resident mode, restore the pointer and coordinates that record the last state
151	    // to the initial state. if two blockmmad instances need to be consecutively invoked at the kernel layer,
152	    // RestoreStatus() must be inserted between them.
153	    CATLASS_DEVICE
154	    void RestoreStatus()
155	    {
156	        for (int i = 0; i < L1A_STAGES; ++i) {
157	            lastAddrA[i] = nullptr;
158	            lastCoordA[i] = MatrixCoord{0U, 0U};
159	        }
160	        for (int i = 0; i < L1B_STAGES; ++i) {
161	            lastAddrB[i] = nullptr;
162	            lastCoordB[i] = MatrixCoord{0U, 0U};
163	        }
164	    }
165	
166	    /// Construct
167	    CATLASS_DEVICE
168	    BlockMmadTla(Arch::Resource<ArchTag>& resource, uint32_t l1BufAddrStart = 0)
169	    {
170	        if ASCEND_IS_AIC {
171	            // use HF32 when USE_HF32_MODE is true
172	            if constexpr (USE_HF32_MODE) {
173	                AscendC::SetHF32Mode(true);
174	            } else {
175	                AscendC::SetHF32Mode(false);
176	            }
177	            if constexpr (ENABLE_UNIT_FLAG && tla::detail::isRowMajor<LayoutC>::value) {
178	                AscendC::SetMMLayoutTransform(true);
179	            }
180	            uint32_t l1AOffset = l1BufAddrStart;
181	            uint32_t l1BOffset = l1BufAddrStart + L1A_TILE_SIZE * L1A_STAGES;
182	            // Init buffers
183	            for (uint32_t i = 0; i < L1A_STAGES; i++) {
184	                // Assign L1/L0A/L0B space for each stages
185	                l1ATensorList[i] = resource.l1Buf.template GetBufferByByte<ElementA>(l1AOffset + L1A_TILE_SIZE * i);
186	                // Assign MutexID for each stage
187	                l1AMutexList[i] = static_cast<int32_t>(L1A_MUTEX_OFFSET + i);
188	            }
189	            for (uint32_t i = 0; i < L1B_STAGES; i++) {
190	                // Assign L1/L0A/L0B space for each stages
191	                l1BTensorList[i] = resource.l1Buf.template GetBufferByByte<ElementB>(l1BOffset + L1B_TILE_SIZE * i);
192	                // Assign MutexID for each stage
193	                l1BMutexList[i] = static_cast<int32_t>(L1B_MUTEX_OFFSET + i);
194	            }
195	            for (uint32_t i = 0; i < L0A_STAGES; i++) {
196	                // Assign L1/L0A/L0B space for each stages
197	                l0ATensorList[i] = resource.l0ABuf.template GetBufferByByte<ElementA>(L0A_TILE_SIZE * i);
198	                // Assign MutexID for each stage
199	                l0AMutexList[i] = static_cast<int32_t>(L0A_MUTEX_OFFSET + i);
200	            }
201	            for (uint32_t i = 0; i < L0B_STAGES; i++) {
202	                // Assign L1/L0A/L0B space for each stages
203	                l0BTensorList[i] = resource.l0BBuf.template GetBufferByByte<ElementB>(L0B_TILE_SIZE * i);
204	                // Assign MutexID for each stage
205	                l0BMutexList[i] = static_cast<int32_t>(L0B_MUTEX_OFFSET + i);
206	            }
207	            if constexpr (!ENABLE_UNIT_FLAG) {
208	                for (uint32_t i = 0; i < L0C_STAGES; i++) {
209	                    l0CTensorList[i] = resource.l0CBuf.template GetBufferByByte<ElementAccumulator>(L0C_TILE_SIZE * i);
210	                    l0CMutexList[i] = static_cast<int32_t>(L0C_MUTEX_OFFSET + i);
211	                }
212	            } else {
213	                l0CTensorList[0] = resource.l0CBuf.template GetBufferByByte<ElementAccumulator>(0);
214	                l0CMutexList[0] = static_cast<int32_t>(L0C_MUTEX_OFFSET);
215	            }
216	            if constexpr (HAS_BIAS) {
217	                uint32_t l1BiasOffset = l1BOffset + L1B_TILE_SIZE * L1B_STAGES;
218	                l1BiasTensor = resource.l1Buf.template GetBufferByByte<uint8_t>(l1BiasOffset);
219	                l0BiasTensor = resource.btBuf.template GetBufferByByte<ElementAccumulator>(0);
220	            }
221	
222	            if constexpr (ENABLE_L1_RESIDENT) {
223	                RestoreStatus();
224	            }
225	        }
226	    }
227	
228	    /// Destructor
229	    CATLASS_DEVICE
230	    ~BlockMmadTla()
231	    {
232	        if ASCEND_IS_AIC {
233	            if constexpr (USE_HF32_MODE) {
234	                AscendC::SetHF32Mode(false);
235	            }
236	            if constexpr (ENABLE_UNIT_FLAG && tla::detail::isRowMajor<LayoutC>::value) {
237	                AscendC::SetMMLayoutTransform(false);
238	            }
239	        }
240	    }
241	
242	    /// Perform a block-scoped matrix multiply-accumulate
243	    template <class TensorA, class TensorB, class TensorC, class TensorBias = EmptyClass>
244	    CATLASS_DEVICE void operator()(
245	        TensorA& tensorA, TensorB& tensorB, TensorC& tensorC, GemmCoord const& actualShape,
246	        TensorBias const& tensorBias = {})
247	    {
248	        // Check L1TileShape
249	        if constexpr (HAS_BIAS) {
250	            static constexpr uint32_t BIAS_BUF_SIZE = L0_TILE_N * sizeof(ElementAccumulator);
251	            static constexpr uint32_t L1BIAS_SIZE = L1_TILE_N * sizeof(ElementBias);
252	            static_assert(
253	                BIAS_BUF_SIZE <= ArchTag::BIAS_SIZE, "BIAS_BUF_SIZE exceeding the BT space! Reduce L0_TILE_N");
254	            static_assert(
255	                L1A_TILE_SIZE * L1A_STAGES + L1B_TILE_SIZE * L1B_STAGES + L1BIAS_SIZE <= ArchTag::L1_SIZE,
256	                "L1TileShape exceeding the L1 space!");
257	        }
258	
259	        using CopyGmToL1A = typename TileCopy_::template CopyGmToL1A<TensorA>;
260	        using CopyGmToL1B = typename TileCopy_::template CopyGmToL1B<TensorB>;
261	        CopyGmToL1A copyGmToL1A;
262	        CopyGmToL1B copyGmToL1B;
263	        using CopyL0CToDst = typename TileCopy_::template CopyL0CToDst<TensorC>;
264	        CopyL0CToDst copyL0CToDst;
265	
266	        uint32_t mBlockActual = actualShape.m();
267	        uint32_t kBlockActual = actualShape.k();
268	        uint32_t nBlockActual = actualShape.n();
269	
270	        uint32_t mL1Actual = mBlockActual;
271	        uint32_t nL1Actual = nBlockActual;
272	
273	        auto layoutInL0C = tla::MakeLayoutL0C(mL1Actual, nL1Actual);
274	        auto tensorL0C = tla::MakeTensor(l0CTensorList[l0CListId], layoutInL0C, Arch::PositionL0C{});
275	        auto tensorL0Bias = tla::MakeTensor(l0BiasTensor, L0BIAS_LAYOUT, Arch::PositionBias{});
276	
277	        uint32_t kL1Actual = min(kBlockActual, L1_TILE_K);
278	        // load first matrix A tile from GM to L1
279	        auto tensorL1A = tla::MakeTensor(l1ATensorList[l1AListId], L1A_LAYOUT, Arch::PositionL1{});
280	        auto tensorTileA = GetTileA(tensorA, 0, 0, mBlockActual, kL1Actual);
281	        if constexpr (ENABLE_L1_RESIDENT) {
282	            // If the currently loaded GM pointer and block coordinates are the same as the last loaded ones,
283	            // skip this loading.
284	            if (lastAddrA[l1AListId] != tensorTileA.data().GetPhyAddr() ||
285	                tla::get<0>(tensorTileA.coord()) != lastCoordA[l1AListId].row() ||
286	                tla::get<1>(tensorTileA.coord()) != lastCoordA[l1AListId].column()) {
287	                AscendC::Mutex::Lock<PIPE_MTE2>(l1AMutexList[l1AListId]);
288	                copyGmToL1A(tensorL1A, tensorTileA);
289	                AscendC::Mutex::Unlock<PIPE_MTE2>(l1AMutexList[l1AListId]);
290	                lastCoordA[l1AListId] = MatrixCoord{tla::get<0>(tensorTileA.coord()), tla::get<1>(tensorTileA.coord())};
291	                lastAddrA[l1AListId] = const_cast<__gm__ typename AscendC::GlobalTensor<ElementA>::PrimType*>(
292	                    tensorTileA.data().GetPhyAddr());
293	            }
294	        } else {
295	            AscendC::Mutex::Lock<PIPE_MTE2>(l1AMutexList[l1AListId]);
296	            copyGmToL1A(tensorL1A, tensorTileA);
297	            AscendC::Mutex::Unlock<PIPE_MTE2>(l1AMutexList[l1AListId]);
298	        }
299	
300	        // load first matrix B tile from GM to L1
301	        auto tensorL1B = tla::MakeTensor(l1BTensorList[l1BListId], L1B_LAYOUT, Arch::PositionL1{});
302	        auto tensorTileB = GetTile(tensorB, tla::MakeCoord(0, 0), tla::MakeShape(kL1Actual, nBlockActual));
303	        if constexpr (ENABLE_L1_RESIDENT) {
304	            if (lastAddrB[l1BListId] != tensorTileB.data().GetPhyAddr() ||
305	                tla::get<0>(tensorTileB.coord()) != lastCoordB[l1BListId].row() ||
306	                tla::get<1>(tensorTileB.coord()) != lastCoordB[l1BListId].column()) {
307	                AscendC::Mutex::Lock<PIPE_MTE2>(l1BMutexList[l1BListId]);
308	                copyGmToL1B(tensorL1B, tensorTileB);
309	                AscendC::Mutex::Unlock<PIPE_MTE2>(l1BMutexList[l1BListId]);
310	                lastCoordB[l1BListId] = MatrixCoord{tla::get<0>(tensorTileB.coord()), tla::get<1>(tensorTileB.coord())};
311	                lastAddrB[l1BListId] = const_cast<__gm__ typename AscendC::GlobalTensor<ElementB>::PrimType*>(
312	                    tensorTileB.data().GetPhyAddr());
313	            }
314	        } else {
315	            AscendC::Mutex::Lock<PIPE_MTE2>(l1BMutexList[l1BListId]);
316	            copyGmToL1B(tensorL1B, tensorTileB);
317	            AscendC::Mutex::Unlock<PIPE_MTE2>(l1BMutexList[l1BListId]);
318	        }
319	
320	        if constexpr (HAS_BIAS && !std::is_same_v<TensorBias, EmptyClass>) {
321	            using CopyGmToL1Bias = typename TileCopy::template CopyGmToL1Bias<TensorBias>;
322	            CopyGmToL1Bias copyGmToL1Bias;
323	            auto l1Bias = l1BiasTensor.template ReinterpretCast<ElementBias>();
324	            auto tensorL1Bias = tla::MakeTensor(l1Bias, L1BIAS_LAYOUT, Arch::PositionL1{});
325	            AscendC::Mutex::Lock<PIPE_MTE2>(L1_BIAS_MUTEX_ID);
326	            copyGmToL1Bias(tensorL1Bias, tensorBias);
327	            AscendC::Mutex::Unlock<PIPE_MTE2>(L1_BIAS_MUTEX_ID);
328	        }
329	
330	        uint32_t mL0Loop = CeilDiv<L0_TILE_M>(mL1Actual);
331	        uint32_t nL0Loop = CeilDiv<L0_TILE_N>(nL1Actual);
332	
333	        // main loop
334	        uint32_t kL1Loop = CeilDiv<L1_TILE_K>(kBlockActual);
335	        for (uint32_t kL1Idx = 0; kL1Idx < kL1Loop; kL1Idx++) {
336	            uint32_t l1AListIdNext = (l1AListId + 1 < L1A_STAGES) ? (l1AListId + 1) : 0;
337	            uint32_t l1BListIdNext = (l1BListId + 1 < L1B_STAGES) ? (l1BListId + 1) : 0;
338	            uint32_t kL1ActualNext{0};
339	            // preload next tile from GM to L1
340	            if (kL1Idx < kL1Loop - 1) {
341	                uint32_t kL1IdxNext = kL1Idx + 1;
342	                kL1ActualNext = (kL1IdxNext < kL1Loop - 1) ? L1_TILE_K : (kBlockActual - kL1IdxNext * L1_TILE_K);
343	
344	                // Get L1 tensor for next stage
345	                auto l1ATensor = l1ATensorList[l1AListIdNext];
346	                auto l1BTensor = l1BTensorList[l1BListIdNext];
347	                auto tensorL1A = tla::MakeTensor(l1ATensor, L1A_LAYOUT, Arch::PositionL1{});
348	                auto tensorL1B = tla::MakeTensor(l1BTensor, L1B_LAYOUT, Arch::PositionL1{});
349	                // Get GM tile for next stage
350	                auto tensorTileA = GetTileA(tensorA, 0, kL1IdxNext * L1_TILE_K, mBlockActual, kL1ActualNext);
351	                auto tensorTileB = GetTile(
352	                    tensorB, tla::MakeCoord(kL1IdxNext * L1_TILE_K, 0), tla::MakeShape(kL1ActualNext, nBlockActual));
353	
354	                // load next matrix A tile from GM to L1
355	                if constexpr (ENABLE_L1_RESIDENT) {
356	                    if (lastAddrA[l1AListIdNext] != tensorTileA.data().GetPhyAddr() ||
357	                        tla::get<0>(tensorTileA.coord()) != lastCoordA[l1AListIdNext].row() ||
358	                        tla::get<1>(tensorTileA.coord()) != lastCoordA[l1AListIdNext].column()) {
359	                        AscendC::Mutex::Lock<PIPE_MTE2>(l1AMutexList[l1AListIdNext]);
360	                        copyGmToL1A(tensorL1A, tensorTileA);
361	                        AscendC::Mutex::Unlock<PIPE_MTE2>(l1AMutexList[l1AListIdNext]);
362	                        lastCoordA[l1AListIdNext] =
363	                            MatrixCoord{tla::get<0>(tensorTileA.coord()), tla::get<1>(tensorTileA.coord())};
364	                        lastAddrA[l1AListIdNext] =
365	                            const_cast<__gm__ typename AscendC::GlobalTensor<ElementA>::PrimType*>(
366	                                tensorTileA.data().GetPhyAddr());
367	                    }
368	                } else {
369	                    AscendC::Mutex::Lock<PIPE_MTE2>(l1AMutexList[l1AListIdNext]);
370	                    copyGmToL1A(tensorL1A, tensorTileA);
371	                    AscendC::Mutex::Unlock<PIPE_MTE2>(l1AMutexList[l1AListIdNext]);
372	                }
373	
374	                // load next matrix B tile from GM to L1
375	                if constexpr (ENABLE_L1_RESIDENT) {
376	                    if (lastAddrB[l1BListIdNext] != tensorTileB.data().GetPhyAddr() ||
377	                        tla::get<0>(tensorTileB.coord()) != lastCoordB[l1BListIdNext].row() ||
378	                        tla::get<1>(tensorTileB.coord()) != lastCoordB[l1BListIdNext].column()) {
379	                        AscendC::Mutex::Lock<PIPE_MTE2>(l1BMutexList[l1BListIdNext]);
380	                        copyGmToL1B(tensorL1B, tensorTileB);
381	                        AscendC::Mutex::Unlock<PIPE_MTE2>(l1BMutexList[l1BListIdNext]);
382	                        lastCoordB[l1BListIdNext] =
383	                            MatrixCoord{tla::get<0>(tensorTileB.coord()), tla::get<1>(tensorTileB.coord())};
384	                        lastAddrB[l1BListIdNext] =
385	                            const_cast<__gm__ typename AscendC::GlobalTensor<ElementB>::PrimType*>(
386	                                tensorTileB.data().GetPhyAddr());
387	                    }
388	                } else {
389	                    AscendC::Mutex::Lock<PIPE_MTE2>(l1BMutexList[l1BListIdNext]);
390	                    copyGmToL1B(tensorL1B, tensorTileB);
391	                    AscendC::Mutex::Unlock<PIPE_MTE2>(l1BMutexList[l1BListIdNext]);
392	                }
393	            }
394	
395	            // Get L1 tensor for current stage
396	            auto l1ATensor = l1ATensorList[l1AListId];
397	            auto l1BTensor = l1BTensorList[l1BListId];
398	            tensorL1A = tla::MakeTensor(l1ATensor, L1A_LAYOUT, Arch::PositionL1{});
399	            tensorL1B = tla::MakeTensor(l1BTensor, L1B_LAYOUT, Arch::PositionL1{});
400	            // Get the loop nums on L0
401	            uint32_t kL0Loop = CeilDiv<L0_TILE_K>(kL1Actual);
402	
403	            for (int mL0Idx = 0; mL0Idx < mL0Loop; mL0Idx++) {
404	                uint32_t mL0Actual = (mL0Idx < mL0Loop - 1) ? L0_TILE_M : (mL1Actual - mL0Idx * L0_TILE_M);
405	
406	                for (int kL0Idx = 0; kL0Idx < kL0Loop; kL0Idx++) {
407	                    uint32_t kL0Actual = (kL0Idx < kL0Loop - 1) ? L0_TILE_K : (kL1Actual - kL0Idx * L0_TILE_K);
408	
409	                    // Locate the current tile on L0A
410	                    auto l0ATile = l0ATensorList[l0AListId];
411	                    auto layoutAInL0 = tla::MakeLayout<ElementA, LayoutTagL0A>(mL0Actual, kL0Actual);
412	                    auto tensorL0A = tla::MakeTensor(l0ATile, layoutAInL0, Arch::PositionL0A{});
413	                    // Locate the current tile of matrix A on L1
414	                    auto tensorTileL1A =
415	                        GetTileA(tensorL1A, mL0Idx * L0_TILE_M, kL0Idx * L0_TILE_K, mL0Actual, kL0Actual);
416	
417	                    // Load current tile from L1 to L0A
418	                    AscendC::Mutex::Lock<PIPE_MTE1>(l1AMutexList[l1AListId]);
419	                    AscendC::Mutex::Lock<PIPE_MTE1>(l0AMutexList[l0AListId]);
420	                    copyL1ToL0A(tensorL0A, tensorTileL1A);
421	                    AscendC::Mutex::Unlock<PIPE_MTE1>(l0AMutexList[l0AListId]);
422	                    AscendC::Mutex::Unlock<PIPE_MTE1>(l1AMutexList[l1AListId]);
423	
424	                    bool initC = ((kL1Idx == 0) && (kL0Idx == 0));
425	                    for (int nL0Idx = 0; nL0Idx < nL0Loop; nL0Idx++) {
426	                        uint32_t nL0Actual = (nL0Idx < nL0Loop - 1) ? L0_TILE_N : (nL1Actual - nL0Idx * L0_TILE_N);
427	
428	                        // Locate the current tile on L0B
429	                        auto l0BTile = l0BTensorList[l0BListId];
430	                        auto layoutBInL0 = tla::MakeLayout<ElementB, LayoutTagL0B>(kL0Actual, nL0Actual);
431	                        auto tensorL0B = tla::MakeTensor(l0BTile, layoutBInL0, Arch::PositionL0B{});
432	                        // Locate the current tile of matrix B on L1
433	                        auto tensorTileL1B = GetTile(
434	                            tensorL1B, tla::MakeCoord(kL0Idx * L0_TILE_K, nL0Idx * L0_TILE_N),
435	                            tla::MakeShape(kL0Actual, nL0Actual));
436	
437	                        // Load current tile from L1 to L0B
438	                        AscendC::Mutex::Lock<PIPE_MTE1>(l1BMutexList[l1BListId]);
439	                        AscendC::Mutex::Lock<PIPE_MTE1>(l0BMutexList[l0BListId]);
440	                        copyL1ToL0B(tensorL0B, tensorTileL1B);
441	                        AscendC::Mutex::Unlock<PIPE_MTE1>(l0BMutexList[l0BListId]);
442	                        AscendC::Mutex::Unlock<PIPE_MTE1>(l1BMutexList[l1BListId]);
443	
444	                        if constexpr (HAS_BIAS && !std::is_same_v<TensorBias, EmptyClass>) {
445	                            if (initC) {
446	                                auto l1Bias = l1BiasTensor.template ReinterpretCast<ElementBias>();
447	                                auto tensorL1Bias = tla::MakeTensor(l1Bias, L1BIAS_LAYOUT, Arch::PositionL1{});
448	                                auto tensorTileL1Bias = GetTile(
449	                                    tensorL1Bias, tla::MakeCoord(nL0Idx * L0_TILE_N), tla::MakeShape(nL0Actual));
450	                                // Load bias to l0 biasTable
451	                                AscendC::Mutex::Lock<PIPE_MTE1>(L1_BIAS_MUTEX_ID);
452	                                AscendC::Mutex::Lock<PIPE_MTE1>(L0_BIAS_MUTEX_ID);
453	                                copyL1ToBT(tensorL0Bias, tensorTileL1Bias);
454	                                AscendC::Mutex::Unlock<PIPE_MTE1>(L0_BIAS_MUTEX_ID);
455	                                AscendC::Mutex::Unlock<PIPE_MTE1>(L1_BIAS_MUTEX_ID);
456	                            }
457	                        }
458	                        // Locate the current tile on L0C
459	                        auto tensorTileL0C = GetTile(
460	                            tensorL0C, tla::MakeCoord(mL0Idx * L0_TILE_M, nL0Idx * L0_TILE_N),
461	                            tla::MakeShape(mL0Actual, nL0Actual));
462	
463	                        // If the unit flag is enabled, the unit flag is set according to the calculation progress
464	                        uint8_t unitFlag = 0b00;
465	                        if constexpr (ENABLE_UNIT_FLAG) {
466	                            if ((kL1Idx == kL1Loop - 1) && (mL0Idx == mL0Loop - 1) && (kL0Idx == kL0Loop - 1) &&
467	                                (nL0Idx == nL0Loop - 1)) {
468	                                unitFlag = 0b11;
469	                            } else {
470	                                unitFlag = 0b10;
471	                            }
472	                        }
473	
474	                        AscendC::Mutex::Lock<PIPE_M>(l0AMutexList[l0AListId]);
475	                        AscendC::Mutex::Lock<PIPE_M>(l0BMutexList[l0BListId]);
476	                        if constexpr (!ENABLE_UNIT_FLAG) {
477	                            AscendC::Mutex::Lock<PIPE_M>(l0CMutexList[l0CListId]);
478	                        }
479	                        if constexpr (HAS_BIAS && !std::is_same_v<TensorBias, EmptyClass>) {
480	                            if (initC) {
481	                                AscendC::Mutex::Lock<PIPE_M>(L0_BIAS_MUTEX_ID);
482	                                tileMmad(
483	                                    tensorTileL0C, tensorL0A, tensorL0B, tensorL0Bias, mL0Actual, nL0Actual, kL0Actual,
484	                                    initC, unitFlag);
485	                                AscendC::Mutex::Unlock<PIPE_M>(L0_BIAS_MUTEX_ID);
486	                            } else {
487	                                tileMmad(
488	                                    tensorTileL0C, tensorL0A, tensorL0B, mL0Actual, nL0Actual, kL0Actual, initC,
489	                                    unitFlag);
490	                            }
491	                        } else {
492	                            tileMmad(
493	                                tensorTileL0C, tensorL0A, tensorL0B, mL0Actual, nL0Actual, kL0Actual, initC, unitFlag);
494	                        }
495	
496	                        if constexpr (!ENABLE_UNIT_FLAG) {
497	                            AscendC::Mutex::Unlock<PIPE_M>(l0CMutexList[l0CListId]);
498	                        }
499	                        AscendC::Mutex::Unlock<PIPE_M>(l0BMutexList[l0BListId]);
500	                        AscendC::Mutex::Unlock<PIPE_M>(l0AMutexList[l0AListId]);
501	                        l0BListId = (l0BListId + 1 < L0B_STAGES) ? (l0BListId + 1) : 0;
502	                    }
503	                    l0AListId = (l0AListId + 1 < L0A_STAGES) ? (l0AListId + 1) : 0;
504	                }
505	            }
506	            l1AListId = l1AListIdNext;
507	            l1BListId = l1BListIdNext;
508	            kL1Actual = kL1ActualNext;
509	        }
510	
511	        // copy block out
512	        if constexpr (!ENABLE_UNIT_FLAG) {
513	            AscendC::Mutex::Lock<PIPE_FIX>(l0CMutexList[l0CListId]);
514	            copyL0CToDst(tensorC, tensorL0C);
515	            AscendC::Mutex::Unlock<PIPE_FIX>(l0CMutexList[l0CListId]);
516	            l0CListId = (l0CListId + 1 < L0C_STAGES) ? (l0CListId + 1) : 0;
517	        } else {
518	            copyL0CToDst(tensorC, tensorL0C, 0b11);
519	        }
520	    }
521	
522	protected:
523	    template <class TensorA>
524	    CATLASS_DEVICE auto GetTileA(TensorA& tensorA, uint32_t mIndex, uint32_t kIndex, uint32_t mSize, uint32_t kSize)
525	    {
526	        if constexpr (tla::detail::isVector<LayoutA>::value) {
527	            return GetTile(tensorA, tla::MakeCoord(kIndex), tla::MakeShape(kSize));
528	        } else {
529	            return GetTile(tensorA, tla::MakeCoord(mIndex, kIndex), tla::MakeShape(mSize, kSize));
530	        }
531	    }
532	
533	    // Multi-stage tensors list
534	    AscendC::LocalTensor<ElementA> l1ATensorList[L1A_STAGES];
535	    AscendC::LocalTensor<ElementB> l1BTensorList[L1B_STAGES];
536	    AscendC::LocalTensor<ElementA> l0ATensorList[L0A_STAGES];
537	    AscendC::LocalTensor<ElementB> l0BTensorList[L0B_STAGES];
538	    AscendC::LocalTensor<ElementAccumulator> l0CTensorList[L0C_STAGES];
539	    AscendC::LocalTensor<uint8_t> l1BiasTensor;
540	    AscendC::LocalTensor<ElementAccumulator> l0BiasTensor;
541	
542	    // Multi-stage MutexID list
543	    int32_t l1AMutexList[L1A_STAGES];
544	    int32_t l1BMutexList[L1B_STAGES];
545	    int32_t l0AMutexList[L0A_STAGES];
546	    int32_t l0BMutexList[L0B_STAGES];
547	    int32_t l0CMutexList[L0C_STAGES];
548	
549	    __gm__ typename AscendC::GlobalTensor<ElementA>::PrimType* lastAddrA[L1A_STAGES];
550	    __gm__ typename AscendC::GlobalTensor<ElementB>::PrimType* lastAddrB[L1B_STAGES];
551	    MatrixCoord lastCoordA[L1A_STAGES];
552	    MatrixCoord lastCoordB[L1B_STAGES];
553	
554	    // The id of current stage
555	    uint32_t l1AListId{0};
556	    uint32_t l1BListId{0};
557	    uint32_t l0AListId{0};
558	    uint32_t l0BListId{0};
559	    uint32_t l0CListId{0};
560	
561	    TileMmad tileMmad;
562	    CopyL1ToL0A copyL1ToL0A;
563	    CopyL1ToL0B copyL1ToL0B;
564	    CopyL1ToBT copyL1ToBT;
565	};
566	
567	} // namespace Catlass::Gemm::Block
568	
569	#endif // CATLASS_GEMM_BLOCK_BLOCK_MMAD_PINGPONG_MUTEX_TLA_HPP
