    deviceRowIndex,
    deviceSharedInput,
    groupListType,
    sharedInputWeight,
    sharedInputOffset,
    batch,
    bsdp,
    deviceOut};

MatmulAdapter matmul_op;
if (matmul_op.CanImplement(arguments) != Status::kSuccess) {
    std::cerr << "Cannot implement the arguments" << std::endl;
    cleanupAndFinalize();
    return;
}
sizeWorkspace = matmul_op.GetWorkspaceSize(arguments);
